create table hotel (
	name VARCHAR(50),
	phone VARCHAR(50),
	email VARCHAR(50),
	room_num INT,
	room_type VARCHAR(22),
	check_in DATE,
	check_out DATE,
	base_rate VARCHAR(50),
	actual_rate VARCHAR(50),
	reservation_num VARCHAR(50),
	card_num VARCHAR(50),
	card_type VARCHAR(50),
	card_expiration DATE
);
